import{_ as s,o as t,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Blocs et modèles personnalisés","description":"","frontmatter":{"title":"Blocs et modèles personnalisés"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/custom-blocks.md","filePath":"fr/projects/blocks-for-ha/custom-blocks.md","lastUpdated":1793447386000}'),n={name:"fr/projects/blocks-for-ha/custom-blocks.md"};function o(i,e,l,u,c,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="blocs-et-modeles-personnalises" tabindex="-1">Blocs et modèles personnalisés <a class="header-anchor" href="#blocs-et-modeles-personnalises" aria-label="Permalink to &quot;Blocs et modèles personnalisés&quot;">​</a></h1><p>Le bouton <strong>Block-/Template-Editor</strong> ouvre un éditeur occupant environ <strong>95 % de la largeur et de la hauteur</strong> de l’écran. Il crée plusieurs blocs dans un paquet, avec aperçu Blockly et sorties HA/Jinja. Les définitions sont déclaratives ; aucun générateur JavaScript importé n’est exécuté.</p><h2 id="creer-un-paquet" tabindex="-1">Créer un paquet <a class="header-anchor" href="#creer-un-paquet" aria-label="Permalink to &quot;Créer un paquet&quot;">​</a></h2><ol><li>Renseigner ID, version, nom, auteur, licence et description du paquet.</li><li>Ajouter les blocs puis choisir valeur, condition, action ou déclencheur.</li><li>Déclarer les champs : texte, nombre, case à cocher ou entité, et les entrées de valeurs typées.</li><li>Renseigner le modèle de sortie : expression Jinja pour une valeur/condition, structure YAML native pour une action/déclencheur.</li><li>Vérifier l’aperçu et les diagnostics ; appliquer le paquet.</li></ol><p>Les blocs appliqués apparaissent dans <strong>Personnalisés</strong>, avant la recherche. Les IDs techniques sont placés dans un espace de noms propre au paquet. Les noms de champs, variables et IDs ne sont pas traduits. Les libellés des paquets restent dans la langue de leur auteur.</p><h2 id="copier-telecharger-et-importer" tabindex="-1">Copier, télécharger et importer <a class="header-anchor" href="#copier-telecharger-et-importer" aria-label="Permalink to &quot;Copier, télécharger et importer&quot;">​</a></h2><p><strong>JSON prüfen</strong> vérifie le JSON collé. <strong>ZIP einlesen</strong> lit l’archive du même format. Après vérification, <strong>Übernehmen</strong> installe le paquet localement. JSON et ZIP contiennent la même définition ; ils ne doivent pas contenir du code exécutable arbitraire.</p><p>Les projets de format 3 incluent les définitions des paquets utilisés pour permettre la restauration sur un autre navigateur. Les paquets installés sont également conservés localement. Les collisions de types et imports invalides sont refusés ; le contrôle préalable évite une installation partielle.</p><p>Pour publier, fournir nom, description, auteur, licence, version et image, avec du JSON copiable et des téléchargements JSON/ZIP. Aucune publication automatique depuis l’éditeur. <a href="./catalog/">Catalogue des paquets</a>.</p><h2 id="limites" tabindex="-1">Limites <a class="header-anchor" href="#limites" aria-label="Permalink to &quot;Limites&quot;">​</a></h2><p>Le JSON de définition produit par le <a href="https://docs.blockly.com/guides/create-custom-blocks/blockly-developer-tools/" target="_blank" rel="noreferrer">Blockly Developer Tools</a> décrit la forme d’un bloc, mais ne suffit pas à produire une automatisation HA. Il faut un modèle de sortie et un schéma de paquet vérifiable. Les générateurs Python, PHP, JavaScript, Lua et Dart du Block Factory ne sont pas les générateurs HA/Jinja de ce projet.</p><p>Les menus déroulants personnalisés, champs variable/image, conteneurs d’instructions, mutateurs et entrées dynamiques supplémentaires restent des pistes d’évolution. Les références à des blocs inconnus et les sorties non représentables sont refusées.</p><p>Le <a href="./catalog/sensor-light">paquet capteur et lampe</a> illustre une valeur de capteur, une condition de seuil et une action de luminosité. Tester les résultats et remplacer les entités avant utilisation dans HA.</p><details class="details custom-block"><summary>Référence détaillée issue de la documentation allemande</summary><h2 id="eigene-blocks-und-template-pakete" tabindex="-1">Blocs personnalisés et paquets de modèles (templates) <a class="header-anchor" href="#eigene-blocks-und-template-pakete" aria-label="Permalink to &quot;Blocs personnalisés et paquets de modèles (templates) {#eigene-blocks-und-template-pakete}&quot;">​</a></h2><p>Depuis la version <strong>0.1.18</strong>, l&#39;<strong>éditeur de blocs/modèles</strong> (Block-/Template-Editor) ouvre, à côté du nom de l&#39;automatisation, une fenêtre occupant 95 % de la largeur et de la hauteur de l&#39;écran. Sur les appareils mobiles, elle occupe 98 % de l&#39;espace et dispose d&#39;un défilement interne. Des champs permettent de configurer le bloc ; sur la droite s&#39;affichent un aperçu Blockly, le résultat HA (Home Assistant) avec des exemples de valeurs, ainsi qu&#39;un code JSON du paquet pouvant être copié.</p><h3 id="erstellen-und-ubernehmen" tabindex="-1">Création et application <a class="header-anchor" href="#erstellen-und-ubernehmen" aria-label="Permalink to &quot;Création et application {#erstellen-und-ubernehmen}&quot;">​</a></h3><ol><li>Saisissez l&#39;identifiant du paquet, la version, le nom, l&#39;auteur, la licence et la description, ou sélectionnez <strong>Charger un exemple</strong>.</li><li>Ajoutez un ou plusieurs blocs : <strong>Valeur/Jinja</strong>, <strong>Condition/Jinja</strong>, <strong>Action/HA-YAML</strong> ou <strong>Déclencheur/HA-YAML</strong>.</li><li>Créez des champs (pour du texte, des nombres, des booléens ou des entités) ainsi que des entrées de valeur (pour des nombres, des chaînes de caractères, des booléens ou des valeurs génériques).</li><li>Saisissez l&#39;expression Jinja ou le mappage déclaratif HA, puis vérifiez l&#39;aperçu.</li><li>Cliquez sur <strong>Appliquer</strong> pour installer le paquet localement. Ses blocs seront alors disponibles dans la section <strong>Personnalisé</strong> (Benutzerdefiniert), juste avant la barre de recherche.</li></ol><p>Les expressions Jinja doivent être saisies sans les doubles accolades de modèle. Les espaces réservés (placeholders), tels que <code>${ENTITY}</code>, font référence aux noms des champs ou des entrées. Les champs sont insérés en respectant leur type, tandis que les entrées de valeur sont intégrées sous forme d&#39;expressions entre accolades. Le mappage HA utilise des valeurs JSON complètes, comme <code>{&quot;$field&quot;:&quot;ENTITY&quot;}</code> ou <code>{&quot;$input&quot;:&quot;VALUE&quot;}</code>. L&#39;<a href="/fr/projects/blocks-for-ha/catalog/sensor-light">exemple « Capteur et lumière »</a> illustre l&#39;ensemble de ces mappages.</p><h3 id="zwei-importwege-und-veroffentlichung" tabindex="-1">Deux méthodes d&#39;importation et publication <a class="header-anchor" href="#zwei-importwege-und-veroffentlichung" aria-label="Permalink to &quot;Deux méthodes d&#39;importation et publication {#zwei-importwege-und-veroffentlichung}&quot;">​</a></h3><ul><li><strong>Insérer le code :</strong> Collez le JSON du paquet dans la section « Importer du code JSON ou un fichier ZIP », <strong>vérifiez le JSON</strong>, consultez l&#39;aperçu, puis <strong>validez</strong>.</li><li><strong>Charger un fichier ZIP :</strong> Sélectionnez le fichier du paquet, consultez l&#39;aperçu, puis <strong>validez</strong>.</li></ul><p>Les options <strong>Télécharger le JSON</strong>, <strong>Copier le code</strong> et <strong>Télécharger le catalogue (ZIP)</strong> permettent toutes d&#39;exporter le même paquet. Le fichier ZIP contient <code>block-package.json</code> et <code>README.md</code>. Les pages open source présentent les paquets et proposent du code ainsi que des téléchargements ; le <a href="https://visualstudio.ugso-software.de/blocks" target="_blank" rel="noreferrer">catalogue</a>, quant à lui, dispose de sa propre page dédiée aux paquets de blocs. Les nouvelles publications sont examinées manuellement ; l&#39;éditeur ne procède à aucun téléversement automatique. <a href="/fr/projects/blocks-for-ha/catalog/">Catalogue et exemple</a>.</p><h3 id="speicherung-und-konflikte" tabindex="-1">Stockage et conflits <a class="header-anchor" href="#speicherung-und-konflikte" aria-label="Permalink to &quot;Stockage et conflits {#speicherung-und-konflikte}&quot;">​</a></h3><p>Format de paquet : <code>ugso-ha-block-package</code>, <code>schemaVersion: 1</code> ; les identifiants de paquets ou de blocs sont composés de lettres minuscules, de chiffres et de traits de soulignement simples. Les paquets installés restent stockés dans le navigateur. Le format de projet <strong>3</strong> intègre les paquets utilisés ainsi que leurs dépendances. Les formats de projet 1 et 2 restent lisibles. En cas d&#39;échec lors de l&#39;importation d&#39;un projet, aucune nouvelle définition de paquet n&#39;est installée.</p><p>Des paquets identiques peuvent être réimportés. Un identifiant de paquet (ID) existant associé à un contenu ou une version différente sera rejeté. Pour créer une variante personnalisée, utilisez un nouvel identifiant de paquet ; les mises à jour automatiques et la désinstallation seront implémentées ultérieurement. Les dépendances doivent être présentes dans la version exacte requise, ou être incluses dans le projet. Les dépendances cycliques sont rejetées.</p><p>Limites : 16 paquets installés, 32 blocs par paquet, 12 champs et 8 entrées de valeur par bloc ; le fichier JSON ne doit pas dépasser 500.000 caractères, et le fichier ZIP ne doit pas excéder 1 Mo (compressé ou décompressé). Les fichiers ZIP ne peuvent contenir que les deux fichiers spécifiés.</p><h3 id="grenzen-des-ersten-editors" tabindex="-1">Limites de la première version de l&#39;éditeur <a class="header-anchor" href="#grenzen-des-ersten-editors" aria-label="Permalink to &quot;Limites de la première version de l&#39;éditeur {#grenzen-des-ersten-editors}&quot;">​</a></h3><p>L&#39;éditeur est une interface dédiée, conçue pour HA (Home Assistant) et dotée d&#39;un aperçu Blockly. L&#39;outil original <a href="https://docs.blockly.com/guides/create-custom-blocks/blockly-developer-tools/" target="_blank" rel="noreferrer">Blockly Block Factory</a> n&#39;est pas encore intégré. Le code JSON brut des blocs généré par cet outil ne contient, en soi, aucune fonctionnalité HA et ne constitue pas un paquet UGSo importable. Les générateurs de code (JavaScript, Python, PHP, Lua, Dart) ne sont ni importés ni exécutés.</p><p>Les menus déroulants, champs de variables, images, conteneurs d&#39;instructions, « mutateurs » et connecteurs dynamiques ne sont pas encore disponibles dans l&#39;éditeur (ils figurent sur la feuille de route). Les entrées de valeur font l&#39;objet d&#39;une vérification de type ; les blocs existants qui ne comportent que des champs numériques fixes ne peuvent pas accepter de valeurs numériques dynamiques.</p><p>L&#39;aperçu vérifie la structure du paquet et les structures HA prises en charge, mais n&#39;exécute pas le code Jinja. Les propriétés des appareils et les plages de paramètres valides doivent être vérifiées au sein de HA ; les champs numériques ne permettent pas, pour l&#39;instant, de définir librement des limites minimales ou maximales. L&#39;éditeur n&#39;exécute aucune action HA. L&#39;exportation au format YAML génère des structures natives HA ; Lors de la réimportation YAML, la représentation native correspondante est générée. Les formes de blocs personnalisées initiales sont préservées grâce au fichier de projet JSON.</p></details>',14)])])}const g=s(n,[["render",o]]);export{m as __pageData,g as default};
